// parentLabel formats a device as "name — ip" for the parent <select>,
// omitting the dash when the device has no IP.
func parentLabel(pd store.DeviceRow) string {
	ip := lowestIPStr(pd.IPs)
	if ip == "" {
		return pd.Name
	}
	return pd.Name + " — " + ip
}

// anyOnline reports whether any interface of the device is currently online.
func anyOnline(ifds []IfaceDetail) bool {
	for _, f := range ifds {
		if f.Online {
			return true
		}
	}
	return false
}

